/**
 * JPEG 1x1 real gerado a partir do logo do projeto. Manter uma imagem
 * decodificável aqui evita que os testes E2E dependam de buffers que apenas
 * imitam os bytes de abertura e fechamento do formato.
 */
export const VALID_JPEG_BUFFER = Buffer.from(
  '',
  'base64',
);

/** PNG RGBA 1x1 com IHDR, IDAT e IEND válidos. */
export const VALID_PNG_BUFFER = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR4nGNgAAIAAAUAAXpeqz8AAAAASUVORK5CYII=',
  'base64',
);

/** WebP lossy 1x1 decodificável, com chunk VP8 de 22 bytes. */
export const VALID_WEBP_BUFFER = Buffer.from(
  'UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEADsD+JaQAA3AA/v89',
  'base64',
);
